UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 41, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 42, 7, NULL::text),(3, 170, 30, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 204, 149, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='4bf41a20-6b1b-5b08-8170-6e8d504cdadd' AND md5(a.contenido)='c2d660f103f0b1b52e423f797e2ba8a0' RETURNING a.id,md5(a.contenido) hash;